                  onChange={(e) => setFilters({ ...filters, search: e.target.value })} className={inputCls + ' col-span-2 sm:col-span-1'} />
              </div>
              {visible.length === 0 ? (
                <p className="py-8 text-center text-sm text-slate-500">
                  {filtering ? 'No transactions match your filters.' : 'No transactions in ' + monthLabel(month) + ' yet.'}
                  {filtering && <> <button className="text-indigo-600 underline" onClick={() => setFilters({ categoryId: 'all', type: 'all', search: '' })}>Clear filters</button></>}
                </p>
              ) : (
                <ul className="divide-y divide-slate-100">
